import{_ as a}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as t}from"./chunks/EN.P9aPnFBv.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as i,o as r,c as o,a3 as n}from"./chunks/framework.g9mfNVRQ.js";const f=JSON.parse('{"title":"G6, ONE","description":"","frontmatter":{"source_hash":"5b747a77e0","source_commit":"7a18e7c","i18n_outdated":true},"headers":[],"relativePath":"fr/install/g6.md","filePath":"fr/install/g6.md"}'),l={name:"fr/install/g6.md"};function u(p,s,c,d,m,v){return r(),o("div",null,[...s[0]||(s[0]=[n('<div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Paramètres<br>  Source de données matérielle<br>   Dex</p></div><h3 id="g6-or-dexcom-one" tabindex="-1">G6 ou Dexcom ONE <a class="header-anchor" href="#g6-or-dexcom-one" aria-label="Permalink to &quot;G6 ou Dexcom ONE {#g6-or-dexcom-one}&quot;">​</a></h3><p>Cette page explique comment configurer un émetteur et un capteur Dexcom G6 ou Dexcom ONE avec xDrip. Du point de vue de xDrip, les deux sont le même appareil (même matériel d&#39;émetteur, même protocole BLE) : toutes les étapes ci-dessous s&#39;appliquent donc aux deux.</p><p>La documentation de référence se trouve <a href="https://navid200.github.io/xDrip/docs/Dexcom_page.html" target="_blank" rel="noreferrer">ici</a>.</p><p>Pour le G7 ou le ONE+, consultez plutôt la <a href="./g7.html">page G7, ONE+</a>.</p><h4 id="prerequisites" tabindex="-1">Prérequis <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prérequis {#prerequisites}&quot;">​</a></h4><ul><li>Vérifiez que la configuration de votre téléphone correspond aux <a href="./prerequisites.html">prérequis</a> de xDrip.</li><li>En principe, xDrip et l&#39;application Dexcom ne peuvent pas collecter directement depuis le même émetteur en même temps. Désinstallez l&#39;application Dexcom si xDrip doit être le collecteur. Si vous devez conserver l&#39;application Dexcom, elle seule peut collecter : utilisez alors xDrip en abonné <a href="./companion.html">Companion App</a>.</li></ul><div class="warning custom-block"><p class="custom-block-title">N&#39;appairez pas depuis les paramètres Bluetooth d&#39;Android</p><p>N&#39;essayez jamais d&#39;appairer l&#39;émetteur depuis la page des paramètres Bluetooth d&#39;Android : laissez xDrip déclencher la demande d&#39;appairage et acceptez-la lorsqu&#39;elle vous est proposée. L&#39;émetteur n&#39;émet que quelques secondes toutes les 5 minutes : ne soyez donc pas surpris qu&#39;Android ne l&#39;affiche pas, la plupart du temps, dans les appareils appairés.</p></div><p>La page <a href="./../troubleshoot/systemstatus.html">État du système</a> (menu en haut à gauche) comporte une rubrique « Dex Status » avec les paramètres dont vous aurez besoin tout au long de cette page : ID de l&#39;émetteur, temps écoulé depuis la dernière connexion, version du firmware, jours de l&#39;émetteur et tensions de la batterie.</p><h4 id="dexcom-device-compatibility" tabindex="-1">Compatibilité des appareils Dexcom <a class="header-anchor" href="#dexcom-device-compatibility" aria-label="Permalink to &quot;Compatibilité des appareils Dexcom {#dexcom-device-compatibility}&quot;">​</a></h4><ul><li><strong>Pompe t:slim</strong> : démarrez le capteur G6 <strong>sur la pompe</strong>, pas dans xDrip, et ne le démarrez pas aussi dans xDrip. Après la période de préchauffage, xDrip détectera et reprendra de lui-même la session en cours (appuyez sur <strong>Redémarrer le collecteur</strong> dans la page Classic Status si ce n&#39;est pas le cas). Vous n&#39;avez pas non plus besoin de saisir le code de calibration dans xDrip : seul l&#39;émetteur en a besoin.</li><li><strong>Récepteur Dexcom</strong> : vous pouvez l&#39;utiliser en parallèle de xDrip, mais évitez d&#39;envoyer des commandes de démarrage/arrêt/calibration en double depuis les deux. Si vous devez utiliser le récepteur, démarrez le capteur sur celui-ci et laissez xDrip reprendre la session après le préchauffage. N&#39;arrêtez pas le capteur depuis xDrip en pensant que cela n&#39;affecte que xDrip : cela arrête toute la session sur l&#39;émetteur.</li><li>Vous <strong>ne pouvez pas</strong> utiliser une pompe t:slim et un récepteur Dexcom en même temps (ils ont besoin du même emplacement de l&#39;émetteur), ni xDrip et l&#39;application Dexcom en même temps, sauf si l&#39;application Dexcom est la seule à collecter : xDrip peut alors la suivre via <a href="./companion.html">Companion App</a>.</li></ul><h4 id="before-you-start" tabindex="-1">Avant de commencer <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Avant de commencer {#before-you-start}&quot;">​</a></h4><p>Pour commencer, il vous faut un émetteur et un capteur.</p><div class="info custom-block"><p class="custom-block-title">Expiration de l&#39;émetteur</p><p>Vérifiez les deux dates imprimées sur la boîte de l&#39;émetteur : la date de fabrication et une date d&#39;expédition limite (Ship-By) ou d&#39;utilisation limite (Use-By). N&#39;acceptez pas un émetteur dont la date Ship-By/Use-By est déjà dépassée. Ne sortez pas l&#39;émetteur de sa boîte et n&#39;en touchez pas les contacts avant de vouloir l&#39;utiliser : un compteur de jours interne démarre dès cet instant et ne peut pas être arrêté. La <a href="./../troubleshoot/g6.html#transmitter-warranty">garantie</a> n&#39;est valable que si vous commencez à utiliser l&#39;émetteur dans les 5 mois suivant son expédition, et le dernier jour où vous pouvez démarrer (ou redémarrer) un capteur sur un émetteur G6 est le 99e jour de l&#39;émetteur.</p></div><h4 id="setup-xdrip" tabindex="-1">Configurer xDrip <a class="header-anchor" href="#setup-xdrip" aria-label="Permalink to &quot;Configurer xDrip {#setup-xdrip}&quot;">​</a></h4><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Paramètres<br>  Source de données matérielle<br>   Dex</p></div><p>Vérifiez ensuite les paramètres ci-dessous : la plupart correspondent aux valeurs par défaut de xDrip, il s&#39;agit donc d&#39;une vérification plutôt que d&#39;une reconfiguration. Le rôle de chaque paramètre est décrit dans les pages <a href="#dexcom-advanced-settings-reference">référence des paramètres avancés Dexcom</a>, <a href="./../use/bluetooth.html">Paramètres Bluetooth</a> et <a href="./../use/misc.html">Autres options diverses</a>.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Paramètres<br>  Paramètres de débogage Dexcom</p></div><div class="admonition xdripitem"><p class="admonition-title">Algorithme natif <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Utiliser l&#39;algorithme interne de l&#39;émetteur pour calculer les valeurs de glycémie lorsque cela est possible.</p></div><div class="admonition xdripitem"><p class="admonition-title">Redémarrer le capteur <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Redémarrer automatiquement un capteur lorsqu&#39;il s&#39;arrête</p></div><div class="admonition xdripitem"><p class="admonition-title">Redémarrage préventif <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Redémarrer un capteur avant la fin de la session les jours 6/9 pour éviter le temps de préparation</p></div><p>Laissez les deux options de redémarrage désactivées. Réutiliser le même capteur au-delà de sa session normale est une technique distincte et plus risquée : lisez <a href="./../troubleshoot/g6.html#restarting-a-sensor-beyond-its-normal-session">Redémarrer un capteur</a> avant de l&#39;envisager.</p><div class="admonition xdripitem"><p class="admonition-title">Continuer sans calibrations <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Toujours utiliser les données s&#39;il n&#39;y a pas assez de bonnes calibrations (expérimental!)</p></div><div class="admonition xdripitem"><p class="admonition-title">Réduire le scan <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Utiliser des heuristiques pour minimiser le scan Bluetooth + économie d&#39;énergie</p></div><div class="admonition xdripitem"><p class="admonition-title">Éviter le scan <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Éviter de scanner autant que possible (réduit la consommation de la batterie)</p></div><div class="info custom-block"><p class="custom-block-title">Options de scan</p><p>Réduire le scan et Éviter le scan économisent la batterie mais sont désastreuses sur certains téléphones (Samsung, marques chinoises...). Commencez avec les deux désactivées : n&#39;essayez de les activer, une à la fois, qu&#39;une fois votre connexion fiable.</p></div><div class="admonition xdripitem"><p class="admonition-title">Permettre la dissociation OB1 <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Le collecteur OB1 peut démorcer si il pense que le chiffrement a échoué. Si vous avez des problèmes avec l&#39;association, désactivez cette option. Si vous perdez alors totalement la connexion, assurez-vous qu&#39;elle est activée.</p></div><div class="admonition xdripitem"><p class="admonition-title">Contournement de jumelage spécial <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Some Samsung devices can have an error where they lose the pairing information. This attempts to work around the issue.</p></div><p>Activez Contournement de jumelage spécial sur les téléphones Samsung et certains téléphones chinois.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Paramètres<br>  <a href="./../use/lesscommon.html">Paramètres moins courants</a><br>   <a href="./../use/misc.html">Autres options diverses</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Mode développeur <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Permet de changer les paramètres les plus dangereux qui pourraient tout casser !</p></div><div class="admonition xdripitem"><p class="admonition-title">Invité pour l’optimisation de la batterie <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Sur Android 6+ s&#39;assurer que l&#39;optimisation de la batterie est désactivée (recommandé).</p></div><div class="admonition xdripitem"><p class="admonition-title">Solutions de contournement Wake <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Utiliser des contournements pour éviter le comportement Android non standard de certains terminaux. Sans cela, les collecteurs ne peuvent pas obtenir les données.</p></div><div class="admonition xdripitem"><p class="admonition-title">Utilisation Wakelocks excessive <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Wakelocks anciennes qui peuvent drainer la batterie, mais pourraient être nécessaires pour NightWatch ou Android Wear</p></div><div class="admonition xdripitem"><p class="admonition-title">Afficher les valeurs prédictives <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Vieille méthode - non recommandée !</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Paramètres<br>  <a href="./../use/lesscommon.html">Paramètres moins courants</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Redémarrage du service agressif <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Redémarrer constamment le service de collecte en cas de soupçon de données manquantes. Activer uniquement si vous observez des pertes de données.</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Paramètres<br>  <a href="./../use/lesscommon.html">Paramètres moins courants</a><br>   <a href="./../calibrate/advancedcal.html">Calibration avancée</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Calibration automatique <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Calibrer en utilisant les nouvelles valeurs de glycémies si les conditions semblent pouvoir le faire, sans demander confirmation (expérimental)</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Paramètres<br>  <a href="./../use/lesscommon.html">Paramètres moins courants</a><br>   <a href="./../use/bluetooth.html">Paramètres Bluetooth</a></p></div><div class="admonition xdripitem"><p class="admonition-title">Activer le Bluetooth <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Activer automatiquement bluetooth s&#39;il est éteint lorsqu&#39;on tente de se connecter à un périphérique bluetooth</p></div><div class="admonition xdripitem"><p class="admonition-title">Garde-fou Bluetooth <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Réinitialiser Bluetooth en le désactivant puis réactivant si nous n’obtenons rien pendant 20 minutes</p></div><div class="admonition xdripitem"><p class="admonition-title">Fermer GATT sur déconnexion BLE <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Si le garde-fou Bluetooth s&#39;active souvent alors vous pouvez essayer de décocher cette option pour voir si ça aide</p></div><div class="admonition xdripitem"><p class="admonition-title">Utiliser le scan <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Scanner avant de se connecter sur xBridge et Bluetooth Libre</p></div><div class="admonition xdripitem"><p class="admonition-title">Use BLE manager <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Use a more modern BLE manager system</p></div><div class="admonition xdripitem"><p class="admonition-title">Faire confiance à Auto-Connect <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Utiliser et faire confiance à la fonctionnalité de connexion auto Bluetooth d&#39;Android</p></div><p>Commencez avec Faire confiance à Auto-Connect désactivé. N&#39;essayez de l&#39;activer que si vous perdez sans cesse la connexion.</p><div class="admonition xdripitem"><p class="admonition-title">Utiliser les scans en arrière-plan <span class="symbol"><img src="'+t+'" style="zoom:75%;"></span></p><p> Utiliser la fonction de scan en arrière-plan d&#39;Android 8+</p></div><div class="admonition xdripitem"><p class="admonition-title">Companion Bluetooth <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Use Bluetooth with companion app data source</p></div><div class="admonition xdripitem"><p class="admonition-title">Wakelocks Bluetooth <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Anciens wakelocks Bluetooth qui peuvent drainer la batterie un peu plus, mais pourraient être nécessaire pour la réception bluetooth</p></div><div class="admonition xdripitem"><p class="admonition-title">Mode de sondage xBridge+ <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Support expérimental pour la fonction de sondage xBridge+</p></div><h4 id="setting-up-for-the-first-time" tabindex="-1">Première configuration <a class="header-anchor" href="#setting-up-for-the-first-time" aria-label="Permalink to &quot;Première configuration {#setting-up-for-the-first-time}&quot;">​</a></h4><div class="warning custom-block"><p class="custom-block-title">Soyez patient</p><p>Ne vous précipitez pas sur « Démarrer le capteur », même si xDrip vous y invite. Suivez les étapes ci-dessous dans l&#39;ordre pour éviter les problèmes les plus courants.</p></div><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Paramètres<br>  Source de données matérielle<br>   Dex</p></div><ol><li>Si vous utilisez un émetteur neuf, notez son numéro de série, imprimé sur l&#39;émetteur et sur sa boîte. Il s&#39;active dès que vous l&#39;enclenchez dans un capteur, et vous aurez besoin de ce numéro pendant 110 jours au maximum. Si le numéro de série se termine par <code>-1</code>, n&#39;utilisez que les six premiers caractères.</li><li>Chaque capteur a un code de calibration à 4 chiffres imprimé sur la protection de l&#39;adhésif : vous en aurez besoin pour démarrer la session. N&#39;ouvrez pas l&#39;emballage du capteur avant d&#39;être prêt à l&#39;insérer, et ne jetez pas la protection de l&#39;adhésif avant d&#39;avoir noté le code.</li><li>Si une commande est bloquée dans la file d&#39;attente de la page Dex Status, <a href="./../troubleshoot/g6.html#transmitter-queue-stuck">videz la file</a> avant de continuer.</li><li>Si « Démarrer le capteur » n&#39;est pas proposé dans le menu en haut à gauche, appuyez plutôt sur « Arrêter le capteur » et attendez 5 minutes.</li><li>L&#39;émetteur doit être détaché de votre corps depuis au moins 10 minutes avant de continuer : <a href="./../troubleshoot/g6.html#removing-a-transmitter-without-damaging-the-sensor">retirer l&#39;émetteur sans endommager le capteur</a> explique comment faire si vous le récupérez sur un capteur précédent.</li><li>Si vous activez un émetteur neuf, saisissez son numéro de série comme <a href="#dexcom-transmitter-id">ID de l&#39;émetteur Dexcom</a>.</li><li>Nettoyez les contacts de l&#39;émetteur à l&#39;alcool (sautez cette étape si vous redémarrez le même capteur) et laissez-les sécher une dizaine de secondes. Enclenchez l&#39;émetteur dans le capteur : c&#39;est ce qui active un émetteur neuf.</li><li>Insérez le capteur en suivant les instructions de l&#39;applicateur du fabricant. Tenez la poussière et le sang à l&#39;écart des contacts.</li><li>Surveillez la page Dex Status de l&#39;<a href="./../troubleshoot/systemstatus.html">État du système</a> : elle se met à jour toutes les 5 minutes. Ne continuez pas tant que la connexion n&#39;est pas correcte ; réglez d&#39;abord ce problème. Si vous activez un émetteur neuf, soyez patient et attendez que les tensions de la batterie s&#39;affichent avant de continuer : cela peut prendre jusqu&#39;à une demi-heure.</li><li>Appuyez sur Démarrer le capteur et saisissez, lorsqu&#39;il vous est demandé, le code de calibration à 4 chiffres figurant sur la protection de l&#39;adhésif du capteur. Conservez ce code : vous pourriez en avoir besoin plus tard.</li></ol><div class="warning custom-block"><p class="custom-block-title">Ne faites jamais de pré-trempage</p><p>Ne faites jamais de pré-trempage (insérer un capteur un certain temps avant de le démarrer dans xDrip). La calibration d&#39;usine est le principal avantage du G6/ONE sur le G5, et le pré-trempage la perturbe. Plus l&#39;écart entre l&#39;insertion du capteur et son démarrage est long, plus vous dégradez cette précision.</p></div><p>Les valeurs arrivent normalement environ 2 heures après le démarrage du capteur, sans étalonnage initial. Si vous venez du G5 ou d&#39;un autre CGM, laissez sa chance à la calibration d&#39;usine : la plupart des gens n&#39;ont pas du tout besoin d&#39;étalonner un capteur G6/ONE, pour peu que le code de calibration ait été saisi correctement.</p><h4 id="starting-a-subsequent-sensor" tabindex="-1">Démarrer un capteur suivant <a class="header-anchor" href="#starting-a-subsequent-sensor" aria-label="Permalink to &quot;Démarrer un capteur suivant {#starting-a-subsequent-sensor}&quot;">​</a></h4><p>Lorsque la session d&#39;un capteur se termine, un même émetteur peut être transféré sur un nouveau capteur et réutilisé : jusqu&#39;à environ 11 capteurs sur sa durée de vie.</p><ol><li>Appuyez sur Arrêter le capteur dans le menu en haut à gauche (même si le capteur s&#39;est déjà arrêté et que « Démarrer le capteur » n&#39;est pas encore proposé). Attendez que « stop sensor » quitte la file d&#39;attente de la page Dex Status, ce qui prend normalement environ 5 minutes.</li><li><a href="./../troubleshoot/g6.html#removing-a-transmitter-without-damaging-the-sensor">Retirez l&#39;ancien émetteur sans endommager le capteur</a> dans lequel il se trouve, pour conserver le site adhésif du capteur, ou décollez simplement l&#39;ancien capteur si vous n&#39;en avez plus besoin.</li><li>Reprenez <a href="#setting-up-for-the-first-time">Première configuration</a> à partir de l&#39;étape 5, avec le code de calibration du nouveau capteur.</li></ol><div class="info custom-block"><p class="custom-block-title">Remarque</p><p>Réutiliser le <em>même</em> capteur au-delà de sa session normale en amenant l&#39;émetteur à le redémarrer est une technique distincte et plus risquée, avec un réel risque de valeurs hautes erronées : consultez <a href="./../troubleshoot/g6.html#restarting-a-sensor-beyond-its-normal-session">Redémarrer un capteur</a> dans le dépannage avant de vous y essayer.</p></div><h4 id="calibration" tabindex="-1">Étalonnage <a class="header-anchor" href="#calibration" aria-label="Permalink to &quot;Étalonnage {#calibration}&quot;">​</a></h4><p>Consultez <a href="./../calibrate/101.html">Les bases de l&#39;étalonnage</a> et <a href="./../calibrate/calibrate.html">Étalonner</a> pour savoir ce qu&#39;est l&#39;étalonnage et quand le faire. Avec la calibration d&#39;usine, vous ne devriez normalement pas du tout avoir besoin d&#39;étalonner un capteur G6/ONE : le fabricant déconseille lui aussi les étalonnages trop fréquents.</p><p>Si vous devez étalonner, appuyez sur « Ajouter Calibration » dans le menu en haut à gauche. Cette option n&#39;est disponible qu&#39;après au moins 3 valeurs reçues depuis le démarrage ou le redémarrage du capteur. N&#39;étalonnez que lorsque la tendance est plate ou presque, et ne saisissez jamais une calibration qui corrige la valeur actuelle de plus de 20 %. Si vous avez besoin d&#39;une correction plus importante, espacez les calibrations successives d&#39;au moins 25 minutes (45 minutes avant une troisième) plutôt que de tout corriger en une seule fois : sinon, vous risquez une erreur de calibration confuse (« confused ») qui peut interrompre les valeurs pendant des heures, sans aucun moyen de savoir combien de temps prendra le rétablissement.</p><h4 id="problems" tabindex="-1">Des problèmes ? <a class="header-anchor" href="#problems" aria-label="Permalink to &quot;Des problèmes ? {#problems}&quot;">​</a></h4><p>Consultez la page <a href="./../troubleshoot/g6.html">Dépannage G6, ONE</a>.</p><br><hr><h3 id="dexcom-advanced-settings-reference" tabindex="-1">Référence des paramètres avancés Dexcom <a class="header-anchor" href="#dexcom-advanced-settings-reference" aria-label="Permalink to &quot;Référence des paramètres avancés Dexcom {#dexcom-advanced-settings-reference}&quot;">​</a></h3><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Paramètres<br>  ID de l&#39;émetteur Dexcom<br>  Paramètres de débogage Dexcom</p></div><p>La documentation de référence se trouve <a href="https://navid200.github.io/xDrip/docs/Dexcom_page.html" target="_blank" rel="noreferrer">ici</a>.</p><br><h4 id="dexcom-transmitter-id" tabindex="-1">ID de l&#39;émetteur Dexcom <a class="header-anchor" href="#dexcom-transmitter-id" aria-label="Permalink to &quot;ID de l&#39;émetteur Dexcom {#dexcom-transmitter-id}&quot;">​</a></h4><p>Indique à xDrip quel émetteur rechercher, auprès duquel s&#39;authentifier, et auquel associer le trafic BLE entrant.</p><p><em>Collecteur : collecteurs Dexcom et chemins de transmetteurs liés à Dex (Dexcom G5/G6/G7 et certaines configurations de transmetteur Dex)</em></p><div class="admonition xdrip"><p class="admonition-title"><img src="'+a+'" style="zoom:75%;"></p><p> Paramètres<br>  ID de l&#39;émetteur Dexcom</p></div><div class="admonition xdripitem"><p class="admonition-title">ID de l&#39;émetteur Dexcom</p><p> ID de votre Transmetteur Dexcom, par exemple 12AB3</p></div><p>Saisissez le numéro de série de l&#39;émetteur (seulement les six premiers caractères s&#39;il se termine par <code>-1</code>).</p><h4 id="native-algorithm" tabindex="-1">Algorithme natif <a class="header-anchor" href="#native-algorithm" aria-label="Permalink to &quot;Algorithme natif {#native-algorithm}&quot;">​</a></h4><p>Utilise, lorsqu&#39;elle est prise en charge, la requête de glycémie/eGlucose propre à l&#39;émetteur, au lieu du chemin des données brutes du capteur.</p><p><em>Collecteur : collecteur Dex OB1 (<code>Ob1G5CollectionService</code>), Dexcom G5/G6/G7</em></p><div class="admonition xdripitem"><p class="admonition-title">Algorithme natif</p></div><h4 id="minimize-scanning" tabindex="-1">Réduire le scan <a class="header-anchor" href="#minimize-scanning" aria-label="Permalink to &quot;Réduire le scan {#minimize-scanning}&quot;">​</a></h4><p>Réduit la fréquence des scans à l&#39;aide d&#39;heuristiques de synchronisation et d&#39;appareils connus, pour économiser la batterie.</p><p><em>Collecteur : collecteur Dex OB1 (<code>Ob1G5CollectionService</code>), Dexcom G5/G6/G7</em></p><div class="admonition xdripitem"><p class="admonition-title">Réduire le scan</p></div><h4 id="avoid-scanning" tabindex="-1">Éviter le scan <a class="header-anchor" href="#avoid-scanning" aria-label="Permalink to &quot;Éviter le scan {#avoid-scanning}&quot;">​</a></h4><p>Pousse plus loin la réduction des scans, en s&#39;appuyant davantage sur la synchronisation et l&#39;identité déjà connues de l&#39;émetteur.</p><p><em>Collecteur : collecteur Dex OB1 (<code>Ob1G5CollectionService</code>), Dexcom G5/G6/G7</em></p><div class="admonition xdripitem"><p class="admonition-title">Éviter le scan</p></div><h4 id="allow-ob1-unbonding" tabindex="-1">Permettre la dissociation OB1 <a class="header-anchor" href="#allow-ob1-unbonding" aria-label="Permalink to &quot;Permettre la dissociation OB1 {#allow-ob1-unbonding}&quot;">​</a></h4><p>Permet à xDrip de supprimer puis de recréer l&#39;association BLE lorsque l&#39;appairage ou le chiffrement Dexcom se retrouve dans un mauvais état.</p><p><em>Collecteur : collecteur Dex OB1 (<code>Ob1G5CollectionService</code>), Dexcom G5/G6/G7</em></p><div class="admonition xdripitem"><p class="admonition-title">Permettre la dissociation OB1</p></div><h4 id="special-pairing-workaround" tabindex="-1">Contournement de jumelage spécial <a class="header-anchor" href="#special-pairing-workaround" aria-label="Permalink to &quot;Contournement de jumelage spécial {#special-pairing-workaround}&quot;">​</a></h4><p>Modifie la séquence d&#39;appairage/connexion OB1 pour contourner des problèmes d&#39;association propres à certains appareils.</p><p><em>Collecteur : collecteur Dex OB1 (<code>Ob1G5CollectionService</code>), Dexcom G5/G6/G7, en particulier sur les modèles de téléphones problématiques</em></p><div class="admonition xdripitem"><p class="admonition-title">Contournement de jumelage spécial</p></div><h4 id="manual-slot-number-engineering" tabindex="-1">Manual Slot Number (mode développeur) <a class="header-anchor" href="#manual-slot-number-engineering" aria-label="Permalink to &quot;Manual Slot Number (mode développeur) {#manual-slot-number-engineering}&quot;">​</a></h4><p>Remplace l&#39;emplacement d&#39;authentification utilisé dans le processus d&#39;authentification Dexcom, pour les cas de développement/dépannage.</p><p><em>Collecteur : collecteur Dex OB1 (<code>Ob1G5CollectionService</code>), Dexcom G5/G6/G7</em></p><div class="admonition xdripitem"><p class="admonition-title">Manual Slot Number</p><p> Specify transmitter slot manually, setting this incorrectly will prevent any readings being received.</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Dernière modification le 23/11/2026</em></a></p>',104)])])}const z=i(l,[["render",u]]);export{f as __pageData,z as default};
